(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.QuadraticLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fraction(n,d=1){return num.fractionTex(num.rational(n,d));}
function formula(a,b,c){return 'f(x)='+(a===1?'':a===-1?'-':String(a))+'x^2'+(b===0?'':(b>0?'+':'-')+(Math.abs(b)===1?'':Math.abs(b))+'x')+(c===0?'':c>0?'+'+c:String(c));}
function rootsTex(a,b,c,delta){if(delta<0)return '\\text{Tidak ada akar real}';if(delta===0)return 'x='+fraction(-b,2*a);const root=Math.sqrt(delta);if(Number.isInteger(root)){const values=[num.rational(-b-root,2*a),num.rational(-b+root,2*a)].sort((p,q)=>p.n/p.d-q.n/q.d);return 'x='+num.fractionTex(values[0])+'\\quad\\text{atau}\\quad x='+num.fractionTex(values[1]);}const n=a>0?-b:b,d=2*Math.abs(a);return `x=\\frac{${n}\\pm\\sqrt{${delta}}}{${d}}`;}
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);}
function tick(n,left,top){const e=document.createElement('span');e.className='transform-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#quad-ticks').append(e);}
for(let n=-5;n<=5;n++){const p=core.point(n,n);svg('line',{x1:p.x,x2:p.x,y1:30,y2:330},$('#quad-grid'));svg('line',{x1:30,x2:330,y1:p.y,y2:p.y},$('#quad-grid'));tick(n,p.x/3.6,53);if(n!==0)tick(n,47,p.y/3.6);}
function draw(){const a=Number($('#quad-a').value)*($('#negative-a').checked?-1:1),b=Number($('#quad-b').value),c=Number($('#quad-c').value),r=core.analyze(a,b,c),h=fraction(-b,2*a),k=fraction(4*a*c-b*b,4*a),vertex=core.point(r.h,r.k);$('#a-output').value=Math.abs(a);$('#b-output').value=b;$('#c-output').value=c;const commands=[];for(let i=0;i<=300;i++){const x=-5+i/30,p=core.point(x,core.value(a,b,c,x));commands.push(`${i===0?'M':'L'}${p.x} ${p.y}`);}$('#quad-curve').setAttribute('d',commands.join(' '));$('#quad-vertex').setAttribute('cx',vertex.x);$('#quad-vertex').setAttribute('cy',vertex.y);$('#symmetry-line').setAttribute('x1',vertex.x);$('#symmetry-line').setAttribute('x2',vertex.x);$('#root-dots').replaceChildren();for(const x of r.roots){const p=core.point(x,0);svg('circle',{cx:p.x,cy:p.y,r:5.5,fill:r.delta===0?'none':'#7d6591',stroke:r.delta===0?'#7d6591':'white'},$('#root-dots'));}math($('#quad-formula'),formula(a,b,c));math($('#vertex-summary'),`P=(${h},${k}),\\qquad x=${h}`);math($('#discriminant-summary'),`\\Delta=b^2-4ac=${r.delta}`);math($('#roots-summary'),rootsTex(a,b,c,r.delta));math($('#quad-range'),`D=\\mathbb R,\\qquad R_f=${a>0?'['+k+',\\infty)':'(-\\infty,'+k+']'}`);$('#quad-feedback').innerHTML=`Puncaknya <span data-tex="(${h},${k})"></span>, dan sumbu simetrinya <span data-tex="x=${h}"></span>. Parabola terbuka ke ${a>0?'atas':'bawah'}, sehingga nilai ${a>0?'minimum':'maksimum'} adalah <span data-tex="${k}"></span>. `+(r.delta>0?'Ada dua akar real berbeda.':r.delta===0?'Ada satu akar real berbeda (akar kembar).':'Tidak ada akar real; grafik tetap terdefinisi pada semua masukan real.')+` Titik potong sumbu tegaknya <span data-tex="(0,${c})"></span>.`;$('#quad-plot').setAttribute('aria-label',`Parabola dengan koefisien a ${a}, b ${b}, c ${c}. Puncak (${r.h}, ${r.k}). Diskriminan ${r.delta}. Ada ${r.roots.length} akar real berbeda.`);}
['quad-a','quad-b','quad-c'].forEach(id=>$('#'+id).addEventListener('input',draw));$('#negative-a').addEventListener('change',draw);$('#reset-quad').addEventListener('click',()=>{$('#quad-a').value=1;$('#quad-b').value=-2;$('#quad-c').value=-2;$('#negative-a').checked=false;draw();});draw();
const questions=[{tex:'f(x)=x^2-4x+3',prompt:'Berapa koordinat mendatar puncaknya?',n:2,hint:'Gunakan negatif koefisien linear dibagi dua kali koefisien kuadrat.',why:'Negatif dari negatif empat dibagi dua menghasilkan dua. Sumbu simetrinya melalui masukan dua.'},{tex:'f(x)=x^2-4x+3',prompt:'Berapa nilai minimum fungsi ini pada domain bilangan real?',n:-1,hint:'Masukkan koordinat mendatar puncak, yaitu dua, ke fungsi semula.',why:'Empat dikurangi delapan ditambah tiga sama dengan negatif satu. Karena terbuka ke atas, nilai ini adalah minimum.'},{tex:'2x^2+3x-2=0',prompt:'Berapa diskriminan persamaan ini?',n:25,hint:'Kuadratkan tiga, lalu kurangi empat kali dua kali negatif dua.',why:'Sembilan dikurangi negatif enam belas menghasilkan dua puluh lima. Diskriminan positif berarti ada dua akar real berbeda.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya -1.':'Belum tepat. Periksa koefisien, tanda negatif, dan operasi yang dipakai.');}));
const choices=[{tex:'f(x)=x^2-4x+3=(x-1)(x-3)',prompt:'Apa akar fungsi ini?',options:['Negatif satu dan negatif tiga.','Satu dan tiga.','Hanya empat.'],answer:1,why:'Hasil kali nol jika faktor pertama atau kedua nol. Masukan satu atau tiga membuat salah satu faktor nol.'},{tex:'f(x)=x^2+1',prompt:'Pernyataan mana yang benar pada bilangan real?',options:['Domainnya kosong karena tidak ada akar real.','Grafiknya tidak ada karena diskriminannya negatif.','Domainnya semua bilangan real, tetapi tidak ada akar real.'],answer:2,why:'Kuadrat ditambah satu selalu paling sedikit satu. Fungsinya terdefinisi pada semua masukan real, tetapi keluarannya tidak pernah nol.'},{tex:'f(x)=-x^2+4x+1',prompt:'Berapa nilai maksimum fungsi ini pada domain bilangan real?',options:['Lima.','Satu.','Tidak memiliki maksimum.'],answer:0,why:'Puncaknya berada pada masukan dua dan keluarannya lima. Parabola terbuka ke bawah, sehingga lima adalah maksimum.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-quadratic-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-quadratic-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();